"use client";
import { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";

export default function Register() {
  const [form, setForm] = useState({
    username: "",
    email: "",
    password: "",
    re_password: "",
  });
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await axios.post("http://127.0.0.1:8000/api/auth/users/", {
        username: form.username,
        email: form.email.toLowerCase(), // ← important
        password: form.password,
        re_password: form.re_password, // ← must be exactly this name
      });
      alert("Registered successfully! Now login");
      router.push("/login");
    } catch (err: any) {
      console.log(err.response?.data);
      alert(err.response?.data?.password?.[0] || "Registration failed");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center">
      <form
        onSubmit={handleSubmit}
        className="bg-white p-10 rounded-3xl shadow-2xl w-96"
      >
        <h2 className="text-3xl font-bold text-center mb-8">Create Account</h2>
        <input
          className="w-full p-4 mb-4 border rounded-xl"
          placeholder="Username"
          required
          onChange={(e) => setForm({ ...form, username: e.target.value })}
        />
        <input
          className="w-full p-4 mb-4 border rounded-xl"
          type="email"
          placeholder="Email"
          required
          onChange={(e) => setForm({ ...form, email: e.target.value })}
        />
        <input
          className="w-full p-4 mb-4 border rounded-xl"
          type="password"
          placeholder="Password"
          required
          onChange={(e) => setForm({ ...form, password: e.target.value })}
        />
        <input
          className="w-full p-4 mb-6 border rounded-xl"
          type="password"
          placeholder="Confirm Password"
          required
          onChange={(e) => setForm({ ...form, re_password: e.target.value })}
        />
        <button
          type="submit"
          className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold hover:bg-blue-700"
        >
          Register
        </button>
        <p className="text-center mt-4">
          Already have account?{" "}
          <a href="/login" className="text-blue-600 font-bold">
            Login
          </a>
        </p>
      </form>
    </div>
  );
}
